import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"RouteServiceProvider","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"RouteServiceProvider"},"headers":[],"relativePath":"system-reference/backend/providers/route-service-provider.md","filePath":"system-reference/backend/providers/route-service-provider.md","lastUpdated":1778363927000}'),r={name:"system-reference/backend/providers/route-service-provider.md"},a=o('<h1 id="routeserviceprovider" tabindex="-1">RouteServiceProvider <a class="header-anchor" href="#routeserviceprovider" aria-label="Permalink to &quot;RouteServiceProvider&quot;">​</a></h1><p><strong>Class</strong>: <code>Unusualify\\Modularous\\Providers\\RouteServiceProvider</code><br><strong>Source</strong>: <code>src/Providers/RouteServiceProvider.php</code><br><strong>Extends</strong>: <code>Illuminate\\Foundation\\Support\\Providers\\RouteServiceProvider</code></p><p>Registers all Modularous system routes, iterates enabled modules to register their routes, and defines the route macros used throughout the application.</p><h2 id="boot" tabindex="-1"><code>boot()</code> <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;`boot()`&quot;">​</a></h2><ol><li>Registers route macros (<code>bootMacros()</code>)</li><li>Registers route middleware aliases (<code>bootRouteMiddlewares()</code> → <code>ModularousRoutes::generateRouteMiddlewares()</code>)</li><li>Loads <code>routes/channels.php</code> for broadcasting</li><li>Calls <code>parent::boot()</code> which triggers <code>map()</code></li></ol><h2 id="route-map" tabindex="-1">Route Map <a class="header-anchor" href="#route-map" aria-label="Permalink to &quot;Route Map&quot;">​</a></h2><h3 id="system-routes-mapsystemroutes" tabindex="-1">System routes (<code>mapSystemRoutes</code>) <a class="header-anchor" href="#system-routes-mapsystemroutes" aria-label="Permalink to &quot;System routes (`mapSystemRoutes`)&quot;">​</a></h3><table><thead><tr><th>Group</th><th>Middleware</th><th>File</th></tr></thead><tbody><tr><td>Auth routes</td><td><code>web</code> + default middlewares</td><td><code>routes/auth.php</code></td></tr><tr><td>Admin web routes</td><td>Domain-scoped (<code>admin_app_url</code>) + web panel middlewares</td><td><code>routes/web.php</code></td></tr><tr><td>Admin API routes</td><td><code>/api</code> prefix + web panel middlewares</td><td><code>routes/api.php</code></td></tr><tr><td>Front routes</td><td><code>web</code></td><td><code>routes/front.php</code></td></tr><tr><td>Glide image route</td><td>—</td><td><code>GET /{glide.base_path}/{path}</code> → <code>GlideController</code></td></tr></tbody></table><p>The Glide route is only registered when <code>media_library.image_service</code> is set to the Glide service class.</p><h3 id="module-routes-mapmoduleroutes" tabindex="-1">Module routes (<code>mapModuleRoutes</code>) <a class="header-anchor" href="#module-routes-mapmoduleroutes" aria-label="Permalink to &quot;Module routes (`mapModuleRoutes`)&quot;">​</a></h3><p>For each enabled module, six route groups are registered:</p><table><thead><tr><th>Group</th><th>Scope</th><th>Source file</th></tr></thead><tbody><tr><td>Module web (manual)</td><td>Module prefix + admin domain</td><td><code>Routes/web.php</code></td></tr><tr><td>Module front (manual)</td><td><code>app.url</code> domain</td><td><code>Routes/front.php</code></td></tr><tr><td>Module panel (macro)</td><td>Admin domain + panel middlewares</td><td><code>Routes/web.php</code> via <code>Route::moduleRoutes()</code></td></tr><tr><td>Module front (macro)</td><td><code>app.url</code> + web middlewares</td><td><code>Routes/front.php</code> via <code>Route::moduleFrontRoutes()</code></td></tr><tr><td>Module public API</td><td><code>ModularousRoutes::getPublicApiGroupOptions()</code></td><td><code>Routes/public-api.php</code> (if exists)</td></tr><tr><td>Module auth API</td><td><code>ModularousRoutes::getAuthApiGroupOptions()</code></td><td><code>Routes/api.php</code> (if exists)</td></tr><tr><td>Module API (macro)</td><td><code>api.</code> prefix</td><td><code>Routes/api.php</code> via <code>Route::moduleApiRoutes()</code></td></tr></tbody></table><h2 id="route-macros" tabindex="-1">Route Macros <a class="header-anchor" href="#route-macros" aria-label="Permalink to &quot;Route Macros&quot;">​</a></h2><table><thead><tr><th>Macro</th><th>HTTP</th><th>Description</th></tr></thead><tbody><tr><td><code>Route::hasAdmin($name)</code></td><td>—</td><td>Returns the fully-qualified admin route name if it exists, <code>false</code> otherwise</td></tr><tr><td><code>Route::host(...$models)</code></td><td>—</td><td>Delegates to <code>HostRoutingRegistrar::host()</code> for host-based route binding</td></tr><tr><td><code>Route::moduleRoutes($module)</code></td><td>—</td><td>Registers admin panel routes for a module via <code>ModularousRoutes::registerModuleRoutes()</code></td></tr><tr><td><code>Route::moduleFrontRoutes($module)</code></td><td>—</td><td>Registers front-facing routes for a module</td></tr><tr><td><code>Route::moduleApiRoutes($module)</code></td><td>—</td><td>Registers API routes for a module</td></tr><tr><td><code>Route::additionalRoutes($url, $name, $options)</code></td><td>Mixed</td><td>Registers a standard set of extra routes: <code>reorder</code>, <code>restore</code>, <code>bulkRestore</code>, <code>forceDelete</code>, <code>bulkForceDelete</code>, <code>bulkDelete</code>, <code>duplicate</code>, <code>tags</code>, <code>tagsUpdate</code>, <code>assignments</code>, <code>createAssignment</code></td></tr><tr><td><code>Route::apiAdditionalRoutes($url, $name, $options)</code></td><td>Mixed</td><td>Registers API-specific extra routes from <code>ModularousRoutes::getCustomApiRoutes()</code></td></tr></tbody></table><h3 id="additionalroutes-http-verbs" tabindex="-1"><code>additionalRoutes</code> HTTP verbs <a class="header-anchor" href="#additionalroutes-http-verbs" aria-label="Permalink to &quot;`additionalRoutes` HTTP verbs&quot;">​</a></h3><table><thead><tr><th>Route</th><th>Verb</th></tr></thead><tbody><tr><td><code>reorder</code>, <code>bulkPublish</code>, <code>bulkFeature</code>, <code>bulkDelete</code>, <code>bulkRestore</code>, <code>bulkForceDelete</code></td><td>POST</td></tr><tr><td><code>publish</code>, <code>feature</code>, <code>restore</code>, <code>forceDelete</code>, <code>tagsUpdate</code></td><td>PUT</td></tr><tr><td><code>duplicate</code>, <code>preview</code></td><td>PUT <code>/{id}</code></td></tr><tr><td><code>browser</code>, <code>tags</code></td><td>GET</td></tr><tr><td><code>restoreRevision</code></td><td>GET <code>/{id}</code></td></tr><tr><td><code>assignments</code></td><td>GET <code>/{id}/assignments</code></td></tr><tr><td><code>createAssignment</code></td><td>POST <code>/{id}/assignments</code></td></tr></tbody></table>',16),s=[a];function c(i,u,l,n,p,h){return d(),t("div",null,s)}const R=e(r,[["render",c]]);export{b as __pageData,R as default};
